function _misc_GetPeaceTime(ind : Integer) : Float;
begin
   case ind of
      0  : Result := 0;     // No peace time
      1  : Result := 10;    // 10 minutes
      2  : Result := 20;
      3  : Result := 30;
      4  : Result := 45;
      5  : Result := 60;
      6  : Result := 90;
      7  : Result := 120;
      8  : Result := 180;
      9  : Result := 240;
      11 : Result := 15;
   end;
   Result := Result * 60;   // convert to game seconds
end;

